  const bouncePhase = (frame / fps) * Math.PI * 2 * bounceSpeed;
  // Use negative sine so it starts by going down slightly, or positive to go up.
  // We offset it so it mostly bounces downwards from its resting position.
  const bounceY = (Math.sin(bouncePhase) * 0.5 + 0.5) * bounceHeight - (bounceHeight / 2);

  // SVG Path for a clean, sharp downward arrow
